SELECT DISTINCT ?length ?n0 ?e1 ?n1 WHERE {
{ {
SELECT DISTINCT ?source ?target ?n0 WHERE {
  ?n0 <http://www.w3.org/1999/02/22-rdf-syntax-ns#type> ?nodeClass . VALUES ?nodeClass { <https://xgap.test/toy/Person> }
  FILTER(1 = 1)
  BIND(?n0 AS ?source)
  BIND(?n0 AS ?target)
}
}
BIND(0 AS ?length)
}
UNION
{ {
SELECT DISTINCT ?source ?target ?n0 ?n1 ?e1 WHERE {
  ?e1 <http://www.w3.org/1999/02/22-rdf-syntax-ns#type> <https://xgap.test/toy/Edge> .
  ?e1 <https://xgap.test/toy/source> ?n0 .
  ?e1 <https://xgap.test/toy/target> ?n1 .
  ?e1 <https://xgap.test/toy/label> "KNOWS" .
  FILTER(1 = 0)
  BIND(?n0 AS ?source)
  BIND(?n1 AS ?target)
}
}
BIND(1 AS ?length)
}
}

CALL {
MATCH (n0)-[e1]->(n1)
WHERE type(e1) = "KNOWS"
RETURN DISTINCT n0 AS source, n1 AS target, n0 AS n0, n1 AS n1, e1 AS e1
}
RETURN DISTINCT 1 AS length, n0 AS n0, e1 AS e1, n1 AS n1

